ALTER TABLE "personal_provider_credentials" DROP CONSTRAINT "personal_provider_credentials_provider_check";--> statement-breakpoint
ALTER TABLE "personal_provider_credentials" DROP CONSTRAINT "personal_provider_credentials_destination_check";--> statement-breakpoint
ALTER TABLE "personal_provider_credentials" ADD CONSTRAINT "personal_provider_credentials_provider_check" CHECK ("personal_provider_credentials"."provider" in ('typesafe', 'anthropic', 'openai', 'openrouter', 'nautilo-gateway', 'gateway', 'mindswapper', 'google', 'xai', 'fireworks', 'together', 'venice', 'elevenlabs', 'groq', 'tavily', 'browser-use', 'cloudconvert', 'surplus'));--> statement-breakpoint
ALTER TABLE "personal_provider_credentials" ADD CONSTRAINT "personal_provider_credentials_destination_check" CHECK (("personal_provider_credentials"."provider" = 'mindswapper' and nullif("personal_provider_credentials"."destination", '') is not null) or "personal_provider_credentials"."provider" = 'gateway' or ("personal_provider_credentials"."provider" <> 'mindswapper' and "personal_provider_credentials"."destination" is null));